INSERT INTO lessons(course_id,title,description,content,code_language,starter_code,xp,lesson_order) SELECT id,'Physics & Interaction','Collision concepts, forces, triggers and interactive controls.','Physics & Interaction is a guided module in Game & 3D Development. Collision concepts, forces, triggers and interactive controls. Read the concept, try the starter activity, then build a small feature before moving forward.','javascript','const player={x:0,y:0,z:0};',80,4 FROM courses WHERE slug='game-3d';
